CREATE OR REPLACE FUNCTION private.require_drive_live_change_profile_v2392(p_master_uid text, p_itemcode text, p_locationcode text, p_lotcode text)
 RETURNS profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.profiles%rowtype;actor_key text;actor_role text;row_value public.ph_master_inventory%rowtype; matrix public.user_access;
begin
  select p.* into actor from public.profiles p where p.id=auth.uid() and p.disabled_at is null
    and not p.must_change_password and (p.locked_until is null or p.locked_until<=statement_timestamp());
  if actor.id is null then raise exception using errcode='42501',message='DRIVE_LIVE_CHANGE_PROFILE_INACTIVE'; end if;
  IF private.inventory_unrestricted_actor_v23155(actor) THEN RETURN actor; END IF;
  actor_key:=private.normalize_inventory_live_change_username_v2392(actor.username);
  actor_role:=private.normalized_profile_role(actor.role);
  select * into matrix from public.user_access where profile_id=actor.id;
  if matrix.profile_id is not null then
    if matrix.edit_any_row='Y' then return actor; end if;
    if matrix.flyer_folder_access='Y' and exists(select 1 from public.ph_flyer_folder_rows f where f.master_unique_id=p_master_uid) then return actor; end if;
    if matrix.edit_assigned_rows_only<>'Y' and actor_role not in ('EVAL','EVALUATOR') then raise exception 'DRIVE_LIVE_CHANGE_ADMIN_REQUIRED' using errcode='42501'; end if;
  elsif actor_key=any(array['dylan_collyge','megan_kelly','jd_jones','mitch_kaiser','nelly_aguilar','morgan_anderson'])
     or actor_role in ('ADMIN','ADMINISTRATOR','MANAGER') then return actor; end if;
  if matrix.profile_id is null and actor_key<>'jorge_colunga' and actor_role not in ('EVAL','EVALUATOR') then
    raise exception using errcode='42501',message='DRIVE_LIVE_CHANGE_ADMIN_REQUIRED';
  end if;
  select m.* into row_value from public.ph_master_inventory m
  where m.unique_id=btrim(coalesce(p_master_uid,''))
    and upper(btrim(coalesce(m.itemcode,'')))=upper(btrim(coalesce(p_itemcode,'')))
    and upper(btrim(coalesce(m.locationcode,'')))=upper(btrim(coalesce(p_locationcode,'')))
    and upper(btrim(coalesce(m.lotcode,'')))=upper(btrim(coalesce(p_lotcode,''))) limit 1;
  if row_value.unique_id is null or not private.inventory_row_assigned_to_actor_v2392(
    actor_key,row_value.unique_id,row_value.itemcode) then
    raise exception using errcode='42501',message=case when actor_key='jorge_colunga'
      then 'INVENTORY_LIVE_CHANGE_JORGE_ROW_NOT_ASSIGNED' else 'INVENTORY_LIVE_CHANGE_ROW_NOT_ASSIGNED' end;
  end if;
  return actor;
end $function$

CREATE OR REPLACE FUNCTION public.save_request_work_pre_state_machine_v2359(request_id text, expected_version bigint, patch jsonb, complete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
declare
  existing public.ph_requests_pending%rowtype;
  profile public.profiles%rowtype;
  profile_email text;
  canonical jsonb;
  safe_patch jsonb;
  save_result jsonb;
  season_result jsonb;
  linked_itemcode text;
  resulting_version bigint;
  season_token text;
begin
  if not private.can_save_request_work() then
    raise exception using errcode = '42501', message = 'REQUEST_SAVE_FORBIDDEN';
  end if;
  if nullif(btrim(coalesce(request_id, '')), '') is null then
    raise exception using errcode = '22023', message = 'REQUEST_ID_AND_VERSION_REQUIRED';
  end if;
  if patch is null or jsonb_typeof(patch) <> 'object' then
    raise exception using errcode = '22023', message = 'REQUEST_PATCH_INVALID';
  end if;

  select * into existing
  from public.ph_requests_pending
  where unique_id = request_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_NOT_FOUND';
  end if;

  profile := private.current_active_profile();
  if profile.id is null then
    raise exception using errcode = '42501', message = 'REQUEST_PROFILE_REQUIRED';
  end if;
  if lower(btrim(coalesce(profile.username, ''))) in ('ben_brown', 'chance_alldredge') then
    if not private.can_work_request_identity(
      existing.request_created_by_username,
      existing.request_selected_rep_username,
      existing.requested_by
    ) then
      raise exception using errcode = '42501', message = 'REQUEST_ROW_FORBIDDEN';
    end if;
  end if;

  if lower(coalesce(existing.req_status, '')) in ('complete', 'completed')
     or nullif(btrim(coalesce(existing.date_completed, '')), '') is not null then
    canonical := coalesce(private.canonical_request_json(request_id), to_jsonb(existing));
    save_result := jsonb_build_object(
      'row', canonical,
      'row_version', existing.row_version,
      'delivery_state', coalesce((
        select outbox.status
        from public.ph_request_delivery_outbox outbox
        where outbox.request_id = existing.unique_id
          and outbox.event_type = 'request_completed'
        order by outbox.created_at desc
        limit 1
      ), 'already_completed'),
      'acknowledged', true
    );
  else
    expected_version := existing.row_version;

    safe_patch := patch - 'completed_by_username' - 'completed_by_display' - 'completed_by_email';
    if complete then
      select auth_user.email into profile_email
      from auth.users auth_user
      where auth_user.id = profile.id;
      safe_patch := safe_patch || jsonb_build_object(
        'completed_by_username', profile.username,
        'completed_by_display', coalesce(nullif(profile.display_name, ''), profile.username),
        'completed_by_email', coalesce(profile_email, '')
      );
    end if;

    save_result := public.save_request_work_v1(
      request_id, expected_version, safe_patch, complete
    );
  end if;

  if coalesce(complete, false) and existing.master_id is not null then
    select master.itemcode into linked_itemcode
    from public.ph_master_inventory master
    where master.unique_id = existing.master_id;
    if nullif(btrim(coalesce(linked_itemcode, '')), '') is not null then
      resulting_version := coalesce(
        nullif(save_result->>'row_version', '')::bigint,
        existing.row_version
      );
      season_token := 'request-season-' || encode(extensions.digest(
        request_id || '|' || coalesce(resulting_version, 0)::text,
        'sha256'
      ), 'hex');
      begin
        season_result := private.refresh_eligible_season_sales_itemcode_v1(
          linked_itemcode,
          left('request-complete:' || request_id || ':' || coalesce(resulting_version, 0)::text, 180),
          season_token
        );
      exception when others then
        season_result := jsonb_build_object(
          'ok', true,
          'status', 'maintenance_deferred',
          'code', 'MAINTENANCE_DEFERRED'
        );
      end;
      save_result := coalesce(save_result, '{}'::jsonb)
        || jsonb_build_object('season_sales_office', season_result);
    end if;
  end if;

  return save_result;
end
$function$

CREATE OR REPLACE FUNCTION public.save_request_work(request_id text, expected_version bigint, patch jsonb, complete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '8s'
 SET statement_timeout TO '30s'
AS $function$
declare
  history_row public.ph_requests_completed_history%rowtype;
  profile public.profiles%rowtype;
  receipt jsonb;
begin
  if exists(select 1 from public.ph_requests_pending where unique_id=request_id) then
    return public.save_request_work_pre_state_machine_v2359(request_id,expected_version,patch,complete);
  end if;
  if not complete then raise exception using errcode='P0002',message='REQUEST_NOT_FOUND'; end if;
  if not private.can_save_request_work() then
    raise exception using errcode='42501',message='REQUEST_SAVE_FORBIDDEN';
  end if;
  select * into history_row from public.ph_requests_completed_history history where history.unique_id=request_id;
  if history_row.unique_id is null or history_row.date_completed is null then
    raise exception using errcode='P0002',message='REQUEST_NOT_FOUND';
  end if;
  profile:=private.current_active_profile();
  if lower(btrim(coalesce(profile.username,''))) in ('ben_brown','chance_alldredge')
    and not private.can_work_request_identity(
      history_row.request_created_by_username,history_row.request_selected_rep_username,history_row.requested_by
    ) then
    raise exception using errcode='42501',message='REQUEST_ROW_FORBIDDEN';
  end if;
  receipt:=private.request_receipt_json_v1(request_id);
  return jsonb_build_object(
    'row',receipt,'row_version',history_row.row_version,
    'delivery_state',coalesce((select outbox.status from public.ph_request_delivery_outbox outbox
      where outbox.request_id=$1 and outbox.event_type='request_completed'
      order by outbox.created_at desc limit 1),'already_completed'),
    'acknowledged',true,'idempotent_replay',true,
    'lifecycle_state','completed_history','active',false
  );
end
$function$

CREATE OR REPLACE FUNCTION public.request_work_command_v1_pre_state_machine_v2359(p_actor_id uuid, p_session_id uuid, p_operation text, p_request_id text DEFAULT NULL::text, p_expected_version bigint DEFAULT NULL::bigint, p_patch jsonb DEFAULT '{}'::jsonb, p_complete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '5s'
 SET statement_timeout TO '30s'
AS $function$
declare result jsonb; clean jsonb; request_row public.ph_requests_pending%rowtype; master_row public.ph_master_inventory%rowtype; qty numeric; pct numeric;
begin
 if not private.is_service_role_request() or not suspend_tag_private.session_active(p_actor_id,p_session_id) then raise exception 'REQUEST_WORK_SESSION_REQUIRED' using errcode='42501'; end if;
 perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',p_actor_id,'role','authenticated','session_id',p_session_id)::text,true);
 if p_operation='capabilities' then return public.get_request_capabilities(); end if;
 if p_operation not in ('save','append_photo') or jsonb_typeof(p_patch)<>'object' then raise exception 'REQUEST_WORK_OPERATION_INVALID' using errcode='22023'; end if;
 if not private.can_save_request_work() then raise exception 'REQUEST_SAVE_FORBIDDEN' using errcode='42501'; end if;
 if exists(select 1 from jsonb_object_keys(p_patch) k where k not in ('explicit_av_note','force_clear_photos','req_match','req_spec','req_caliper','req_pic_note','req_sales_note','req_comments','av_note','req_reserve','req_photo_link','req_photo_name','req_photo_mode','req_rep_action','request_note','loc_match_qty','drive_photo_link','drive_photo_name','req_status','date_completed','req_archived','requested_by','request_folder','req_customer')) then raise exception 'REQUEST_WORK_FIELD_FORBIDDEN' using errcode='22023'; end if;
 select * into request_row from public.ph_requests_pending where unique_id=p_request_id;
 if not found then raise exception 'REQUEST_NOT_FOUND' using errcode='P0002'; end if;
 if not private.can_work_request_identity(request_row.request_created_by_username,request_row.request_selected_rep_username,request_row.requested_by) then raise exception 'REQUEST_ROW_FORBIDDEN' using errcode='42501'; end if;
 -- Match the import trigger lock order: master first, then its operational request.
 select * into master_row from public.ph_master_inventory where unique_id=request_row.master_id for update;
 if master_row.unique_id is null then
   if nullif(btrim(request_row.master_id),'') is not null then raise exception 'REQUEST_MASTER_NOT_FOUND' using errcode='P0002'; end if;
   if nullif(btrim(request_row.master_id),'') is null then
     select min(candidate.unique_id) into master_row.unique_id from public.ph_master_inventory candidate
       where candidate.itemcode=request_row.itemcode and candidate.locationcode=request_row.locationcode
         and (nullif(btrim(request_row.priority),'') is null or candidate.priority=request_row.priority)
         and (nullif(btrim(request_row.lotcode),'') is not null and candidate.lotcode=request_row.lotcode
           or nullif(btrim(request_row.lotcode),'') is null and nullif(btrim(request_row.priority),'') is not null
            and (nullif(btrim(request_row.source_snapshot->>'season'),'') is not null or nullif(btrim(request_row.source_snapshot->>'saleyear'),'') is not null)
            and (nullif(btrim(request_row.source_snapshot->>'season'),'') is null or candidate.season=request_row.source_snapshot->>'season')
            and (nullif(btrim(request_row.source_snapshot->>'saleyear'),'') is null or candidate.saleyear=request_row.source_snapshot->>'saleyear'))
       having count(*)=1;
     if master_row.unique_id is not null then
       select m.* into master_row from public.ph_master_inventory m where m.unique_id=master_row.unique_id for update;
     end if;
   end if;
   if master_row.unique_id is not null then
     update public.ph_requests_pending set master_id=master_row.unique_id where unique_id=p_request_id;
     request_row.master_id:=master_row.unique_id;
   end if;
 end if;
 select * into request_row from public.ph_requests_pending where unique_id=p_request_id for update;
 if not found then raise exception 'REQUEST_NOT_FOUND' using errcode='P0002'; end if;
 if not private.can_work_request_identity(request_row.request_created_by_username,request_row.request_selected_rep_username,request_row.requested_by) then raise exception 'REQUEST_ROW_FORBIDDEN' using errcode='42501'; end if;
 clean:=p_patch - 'req_status' - 'date_completed' - 'req_archived' - 'loc_match_qty' - 'drive_photo_link' - 'drive_photo_name' - 'requested_by' - 'request_folder' - 'req_customer';
 if p_complete then
   clean:=jsonb_strip_nulls(jsonb_build_object('req_spec',request_row.req_spec,'req_match',request_row.req_match,'req_caliper',request_row.req_caliper,'req_pic_note',request_row.req_pic_note,'av_note',request_row.av_note,'req_photo_link',request_row.req_photo_link,'req_photo_name',request_row.req_photo_name))||clean;
 end if;
 if clean ? 'req_spec' then clean:=jsonb_set(clean,'{req_spec}',to_jsonb(replace(replace(coalesce(clean->>'req_spec',''),chr(92)||chr(39),chr(39)),chr(92)||chr(34),chr(34)))); end if;
 if clean ? 'av_note' then clean:=jsonb_set(clean,'{av_note}',to_jsonb(replace(replace(coalesce(clean->>'av_note',''),chr(92)||chr(39),chr(39)),chr(92)||chr(34),chr(34)))); end if;
 if p_complete and coalesce(nullif(btrim(clean->>'av_note'),''),nullif(btrim(request_row.av_note),'')) is null and nullif(btrim(coalesce(clean->>'req_spec',request_row.req_spec)), '') is not null then clean:=clean||jsonb_build_object('av_note','SPEC - '||coalesce(clean->>'req_spec',request_row.req_spec)); end if;
 if clean ? 'req_photo_link' then clean:=clean||jsonb_build_object('drive_photo_link',clean->>'req_photo_link'); end if;
 if clean ? 'req_photo_name' then clean:=clean||jsonb_build_object('drive_photo_name',clean->>'req_photo_name'); end if;
 if clean ? 'req_match' and coalesce(clean->>'req_match','') ~ '^[0-9]+([.][0-9]+)?$' then
 pct:=(clean->>'req_match')::numeric;
 if pct>100 then raise exception 'REQUEST_MATCH_INVALID' using errcode='22023'; end if;
 if coalesce(master_row.ptronhand,'') ~ '^[0-9]+([.][0-9]+)?$' then qty:=master_row.ptronhand::numeric;
 elsif coalesce(request_row.ptravailable,'') ~ '^[0-9]+([.][0-9]+)?$' then qty:=request_row.ptravailable::numeric; end if;
 if qty is not null then clean:=clean||jsonb_build_object('loc_match_qty',round(qty*pct/100)::text); end if;
 end if;
 if p_operation='append_photo' then
   if p_complete or (p_patch - 'req_photo_link' - 'req_photo_name') <> '{}'::jsonb or coalesce(p_patch->>'req_photo_link','') !~ '^https://[^,[:space:]]+$'
      or nullif(btrim(p_patch->>'req_photo_name'),'') is null or position(',' in p_patch->>'req_photo_name')>0 then
     raise exception 'REQUEST_WORK_PHOTO_INVALID' using errcode='22023';
   end if;
   if master_row.unique_id is null then raise exception 'REQUEST_MASTER_NOT_FOUND' using errcode='P0002'; end if;
   if (p_patch->>'req_photo_link')=any(string_to_array(coalesce(request_row.req_photo_link,''),','))
      and (p_patch->>'req_photo_link')=any(string_to_array(coalesce(master_row.photo_link,''),',')) then
     return jsonb_build_object('ok',true,'lifecycle_state','pending_active','row',to_jsonb(request_row),'row_version',request_row.row_version,'master_row',to_jsonb(master_row));
   end if;
   p_expected_version:=request_row.row_version;
   -- The master and request are both locked. A replay appends each URL at most once.
   clean:=jsonb_build_object(
     'req_photo_link',request_row.req_photo_link,'req_photo_name',request_row.req_photo_name,
     'drive_photo_link',master_row.photo_link,'drive_photo_name',master_row.photo_name);
   if not (p_patch->>'req_photo_link'=any(string_to_array(coalesce(request_row.req_photo_link,''),','))) then
     clean:=clean||jsonb_build_object('req_photo_link',concat_ws(',',nullif(request_row.req_photo_link,''),p_patch->>'req_photo_link'),
       'req_photo_name',concat_ws(',',nullif(request_row.req_photo_name,''),p_patch->>'req_photo_name'));
   end if;
   if not (p_patch->>'req_photo_link'=any(string_to_array(coalesce(master_row.photo_link,''),','))) then
     clean:=clean||jsonb_build_object('drive_photo_link',concat_ws(',',nullif(master_row.photo_link,''),p_patch->>'req_photo_link'),
       'drive_photo_name',concat_ws(',',nullif(master_row.photo_name,''),p_patch->>'req_photo_name'));
   end if;
 end if;
 result:=public.save_request_work(p_request_id,p_expected_version,clean,p_complete);
 select * into master_row from public.ph_master_inventory where unique_id=request_row.master_id;
 return result||jsonb_build_object('master_row',case when master_row.unique_id is null then null else to_jsonb(master_row) end);
end $function$

CREATE OR REPLACE FUNCTION public.request_completion_receipt_v2372(p_actor_id uuid, p_session_id uuid, p_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '3s'
AS $function$
declare
  history_row public.ph_request_history%rowtype;
  receipt jsonb;
begin
  if not private.is_service_role_request()
     or not suspend_tag_private.session_active(p_actor_id,p_session_id) then
    raise exception using errcode='42501',message='REQUEST_WORK_SESSION_REQUIRED';
  end if;
  if exists(select 1 from public.ph_active_request where unique_id=p_request_id) then
    return null;
  end if;
  perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
  perform set_config('request.jwt.claims',jsonb_build_object(
    'sub',p_actor_id,'role','authenticated','session_id',p_session_id
  )::text,true);
  select * into history_row
  from public.ph_request_history history
  where history.unique_id=p_request_id
    and history.date_completed is not null;
  if history_row.unique_id is null
     or not private.can_save_request_work()
     or not private.can_work_request_identity(
       history_row.request_created_by_username,
       history_row.request_selected_rep_username,
       history_row.requested_by
     ) then
    return null;
  end if;
  receipt:=private.request_receipt_json_v1(p_request_id);
  return jsonb_build_object(
    'row',receipt,
    'row_version',history_row.row_version,
    'delivery_state',coalesce((select outbox.status
      from public.ph_request_delivery_outbox outbox
      where outbox.request_id=p_request_id and outbox.event_type='request_completed'
      order by outbox.created_at desc limit 1),'already_completed'),
    'acknowledged',true,
    'idempotent_replay',true,
    'lifecycle_state','completed_history',
    'active',false
  );
end
$function$

CREATE OR REPLACE FUNCTION public.request_work_command_v1(p_actor_id uuid, p_session_id uuid, p_operation text, p_request_id text DEFAULT NULL::text, p_expected_version bigint DEFAULT NULL::bigint, p_patch jsonb DEFAULT '{}'::jsonb, p_complete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '8s'
 SET statement_timeout TO '30s'
AS $function$
declare
  history_row public.ph_requests_completed_history%rowtype;
  master_row public.ph_master_inventory%rowtype;
  result jsonb;
begin
  if p_operation<>'save' or not p_complete
    or exists(select 1 from public.ph_requests_pending where unique_id=p_request_id) then
    return public.request_work_command_v1_pre_state_machine_v2359(
      p_actor_id,p_session_id,p_operation,p_request_id,p_expected_version,p_patch,p_complete
    );
  end if;
  if not private.is_service_role_request()
    or not suspend_tag_private.session_active(p_actor_id,p_session_id) then
    raise exception using errcode='42501',message='REQUEST_WORK_SESSION_REQUIRED';
  end if;
  perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
  perform set_config('request.jwt.claims',jsonb_build_object(
    'sub',p_actor_id,'role','authenticated','session_id',p_session_id
  )::text,true);
  if jsonb_typeof(p_patch)<>'object' then
    raise exception using errcode='22023',message='REQUEST_WORK_OPERATION_INVALID';
  end if;
  select * into history_row from public.ph_requests_completed_history history where history.unique_id=p_request_id;
  if history_row.unique_id is null or history_row.date_completed is null then
    raise exception using errcode='P0002',message='REQUEST_NOT_FOUND';
  end if;
  if not private.can_save_request_work() then
    raise exception using errcode='42501',message='REQUEST_SAVE_FORBIDDEN';
  end if;
  if not private.can_work_request_identity(
    history_row.request_created_by_username,history_row.request_selected_rep_username,history_row.requested_by
  ) then
    raise exception using errcode='42501',message='REQUEST_ROW_FORBIDDEN';
  end if;
  result:=public.save_request_work(p_request_id,p_expected_version,p_patch,true);
  select * into master_row from public.ph_master_inventory where unique_id=history_row.master_id;
  return result||jsonb_build_object(
    'master_row',case when master_row.unique_id is null then null else to_jsonb(master_row) end
  );
end
$function$

CREATE OR REPLACE FUNCTION public.can_upload_drive_evidence_v23115(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE row_value public.ph_master_inventory%ROWTYPE; uid text;
BEGIN
  IF auth.uid() IS NULL OR p_name !~ '^drive-evidence/[a-f0-9]+/(_thumbs/)?v2/[a-f0-9]{64}(-w(144|320))?\.(jpg|webp)$' THEN RETURN false; END IF;
  uid := convert_from(decode(split_part(p_name,'/',2),'hex'),'UTF8');
  SELECT * INTO row_value FROM public.ph_master_inventory WHERE unique_id=uid;
  IF row_value.unique_id IS NULL THEN RETURN false; END IF;
  PERFORM private.require_drive_live_change_profile_v2392(uid,row_value.itemcode,row_value.locationcode,row_value.lotcode);
  RETURN true;
EXCEPTION WHEN insufficient_privilege OR invalid_parameter_value OR character_not_in_repertoire THEN RETURN false;
END $function$
